      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance exposed controllable spin-dependent quantum transport and enabled a far-reaching information technology.",
        "attribution": "The three nominees represent foundational observation and the development of practically decisive magnetic tunnel junctions.",
        "maturity": "The effect is quantitatively established, technologically ubiquitous and supported by a mature physical account.",
        "uncertainties": [
          "Priority and the appropriate division of credit among parallel experimental and device-development contributions require close historical review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Antoine Georges",
        "Gabriel Kotliar",
        "Dieter Vollhardt"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electronic materials quantitatively tractable and transformed the interpretation of their electronic spectra and phases.",
        "attribution": "Georges, Kotliar and Vollhardt provide a plausible compact attribution for the central conceptual and methodological advances.",
        "maturity": "The theory is long established, broadly benchmarked and continuously connected to experiment and materials calculations.",
        "uncertainties": [
          "The contribution is a powerful theoretical framework rather than one discrete discovery, and its credit history is broad."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Bertrand I. Halperin",
        "David R. Nelson",
        "A. Peter Young"
      ],
      "assessment": {
        "nobel_worthiness": "Defect-mediated melting and the hexatic phase supplied a profound account of phase transitions in two dimensions.",
        "attribution": "The nominees cover central theoretical development and testing, though the wider historical framework must be distinguished carefully.",
        "maturity": "Its predictions have motivated extensive experimental, numerical and theoretical scrutiny over many years.",
        "uncertainties": [
          "The exact relation to earlier Kosterlitz-Thouless work and the most appropriate allocation of credit needs careful assessment."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological-insulator framework revealed a robust new class of quantum matter with quantized boundary transport.",
        "attribution": "Kane and Mele supplied the seminal theoretical proposal, while Molenkamp represents decisive experimental establishment.",
        "maturity": "The phenomena are independently reproduced, theoretically coherent and central to contemporary quantum-materials research.",
        "uncertainties": [
          "The candidate overlaps conceptually and personally with related topological-insulator and quantum-anomalous-Hall nominations."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "Sajeev John",
        "John D. Joannopoulos"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps established a compelling analogue of electronic band structure for light and created a durable field of nanophotonics.",
        "attribution": "The credited theorists and experimental pioneer form a coherent representation of the foundational work.",
        "maturity": "The underlying physics is firmly verified and has generated broad experimental and technological consequences.",
        "uncertainties": [
          "Practical impact is distributed across many later photonic-crystal developments, complicating a sharply bounded prize citation."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric phase and the Aharonov-Bohm effect changed the physical understanding of phase, gauge potentials and quantum interference.",
        "attribution": "Berry and Aharonov are clear representatives of the two named foundational effects.",
        "maturity": "Both effects have been repeatedly observed and their concepts now permeate quantum materials, optics and precision quantum physics.",
        "uncertainties": [
          "The two effects have distinct historical origins, so whether they form one sufficiently unified prize requires judgment."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B009",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks achieved an extraordinary advance in frequency metrology and enable stringent tests of fundamental physics.",
        "attribution": "Katori and Ye are credible central figures in the proposal, realization and development of the clock architecture.",
        "maturity": "Independent laboratories have reached exceptional performance and the approach is mature enough for precision applications.",
        "uncertainties": [
          "The eventual impact on time standards and on uniquely enabled fundamental discoveries is still developing."
        ]
      }
    }
  ]
